-- ─── STEP 0: Helper Functions ────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION seed_ts(days_ago INT, hour_offset INT DEFAULT 0)
RETURNS TIMESTAMPTZ LANGUAGE sql STABLE AS $$
  SELECT (NOW() - (days_ago || ' days')::INTERVAL + (hour_offset || ' hours')::INTERVAL)
$$;

