SELECT
  p.id,
  'Retro Arcade',
  'arcade_gamepad',
  (ARRAY['game_2048','snake','tic_tac_toe','sudoku','minesweeper'])[(ROW_NUMBER() OVER (ORDER BY p.created_at) % 5) + 1]::public.cover_game_type,
  'pin',
  crypt('Demo@2024', gen_salt('bf', 10)),
  (ARRAY['dark_modern','dark_neon','vault_gold'])[(ROW_NUMBER() OVER (ORDER BY p.created_at) % 3) + 1],
  (ARRAY[30, 60, 90, 120, 180])[(ROW_NUMBER() OVER (ORDER BY p.created_at) % 5) + 1]
FROM public.profiles p
WHERE p.id BETWEEN '11111111-0001-0001-0001-000000000001'::uuid
               AND '11111111-0030-0030-0030-000000000030'::uuid
ON CONFLICT (user_id) DO NOTHING;

