ON CONFLICT (user_a, user_b) DO NOTHING;

-- ─── STEP 6: DIRECT MESSAGES (500+ DMs) ──────────────────────────────────────
CREATE OR REPLACE FUNCTION seed_conv(a UUID, b UUID) RETURNS UUID LANGUAGE sql STABLE AS $$
  SELECT id FROM public.conversations WHERE user_a = LEAST(a, b) AND user_b = GREATEST(a, b) LIMIT 1;
$$;


ON CONFLICT DO NOTHING;

-- ─── STEP 7: CONVERSATION TIMESTAMPS SYNC ────────────────────────────────────
UPDATE public.conversations c
SET updated_at = (
  SELECT MAX(m.created_at) FROM public.messages m WHERE m.conversation_id = c.id
)
WHERE c.user_a BETWEEN '11111111-0001-0001-0001-000000000001'::uuid
                   AND '11111111-0030-0030-0030-000000000030'::uuid
  AND EXISTS (SELECT 1 FROM public.messages WHERE conversation_id = c.id);

-- ─── STEP 8: READ RECEIPTS & MEMBER SYNCHRONIZATION ─────────────────────────
-- Heavy users: read up to latest message
UPDATE public.conversation_members cm
SET last_read_at = (SELECT MAX(m.created_at) FROM public.messages m WHERE m.conversation_id = cm.conversation_id)
WHERE cm.user_id BETWEEN '11111111-0001-0001-0001-000000000001'::uuid
                     AND '11111111-0005-0005-0005-000000000005'::uuid;

-- Medium users: 2 hours behind
UPDATE public.conversation_members cm
SET last_read_at = NOW() - INTERVAL '2 hours'
WHERE cm.user_id BETWEEN '11111111-0006-0006-0006-000000000006'::uuid
                     AND '11111111-0015-0015-0015-000000000015'::uuid;

-- Casual users: 16 hours behind
UPDATE public.conversation_members cm
SET last_read_at = NOW() - INTERVAL '16 hours'
WHERE cm.user_id BETWEEN '11111111-0016-0016-0016-000000000016'::uuid
                     AND '11111111-0030-0030-0030-000000000030'::uuid;

-- ─── STEP 9: CLEANUP HELPERS ─────────────────────────────────────────────────
DROP FUNCTION IF EXISTS seed_ts(INT, INT);
DROP FUNCTION IF EXISTS seed_conv(UUID, UUID);

